    "status": "GRANTED",
    "text": "GRANTED: agent successor may act on behalf of agent A within scope ['publish', 'request_approval', 'keep_draft']"
  },
  "gate": null,
  "note": "No current restriction record is attached.",
  "probe_actions": [
    {
      "name": "publish",
      "target": "report",
      "requires_grant": true
    },
    {
      "name": "request_approval",
      "target": "report",
      "requires_grant": true
